// Optimisation, small neural networks, search and learning by reward, cause and effect, privacy.
import { mean, sum } from './stats.js';

// ---- going downhill ----
// f(p) -> value, g(p) -> gradient array. Each stepper returns the next point and its own state.
export const steppers = {
  plain: (p, g, s, lr) => ({ p: p.map((v, i) => v - lr * g[i]), s }),
  momentum: (p, g, s, lr, beta = 0.85) => { const v = (s.v || p.map(() => 0)).map((x, i) => beta * x + g[i]); return { p: p.map((x, i) => x - lr * v[i]), s: { v } }; },
  adam: (p, g, s, lr, b1 = 0.9, b2 = 0.999) => { const t = (s.t || 0) + 1, m = (s.m || p.map(() => 0)).map((x, i) => b1 * x + (1 - b1) * g[i]), v = (s.v || p.map(() => 0)).map((x, i) => b2 * x + (1 - b2) * g[i] * g[i]); return { p: p.map((x, i) => x - (lr * (m[i] / (1 - b1 ** t))) / (Math.sqrt(v[i] / (1 - b2 ** t)) + 1e-8)), s: { t, m, v } }; },
};
export function descend(grad, start, { lr = 0.1, steps = 50, how = 'plain' } = {}) { let p = start.slice(), s = {}; const path = [p]; for (let i = 0; i < steps; i++) { const r = steppers[how](p, grad(p), s, lr); p = r.p; s = r.s; path.push(p); if (!p.every(Number.isFinite)) break; } return path; }
export function numGrad(f, p, h = 1e-4) { return p.map((_, i) => { const a = p.slice(), b = p.slice(); a[i] += h; b[i] -= h; return (f(a) - f(b)) / (2 * h); }); }
export function anneal(f, start, neighbour, rng, { T0 = 1, cool = 0.97, steps = 300 } = {}) { let x = start, fx = f(x), best = x, fb = fx, T = T0; const trace = [fx]; for (let i = 0; i < steps; i++) { const y = neighbour(x, rng), fy = f(y); if (fy < fx || rng.chance(Math.exp((fx - fy) / T))) { x = y; fx = fy; if (fx < fb) { best = x; fb = fx; } } T *= cool; trace.push(fx); } return { best, value: fb, trace }; }

// ---- a small fully connected network with back-propagation ----
const ACT = { tanh: [(z) => Math.tanh(z), (a) => 1 - a * a], relu: [(z) => Math.max(0, z), (a) => (a > 0 ? 1 : 0)], sigmoid: [(z) => 1 / (1 + Math.exp(-z)), (a) => a * (1 - a)], linear: [(z) => z, () => 1] };
export function mlp(sizes, rng, act = 'tanh', scale = null) { const layers = []; for (let l = 0; l + 1 < sizes.length; l++) { const s = scale ?? Math.sqrt(2 / (sizes[l] + sizes[l + 1])) * 1.6; layers.push({ W: Array.from({ length: sizes[l + 1] }, () => Array.from({ length: sizes[l] }, () => rng.n(0, s))), b: new Array(sizes[l + 1]).fill(0), act: l + 2 === sizes.length ? 'sigmoid' : act }); } return { layers, sizes }; }
export function forward(net, x) { const acts = [x]; let a = x; for (const L of net.layers) { const f = ACT[L.act][0]; a = L.W.map((row, i) => f(row.reduce((s, w, j) => s + w * a[j], L.b[i]))); acts.push(a); } return acts; }
// one example; returns the size of the gradient at each layer so the fading can be shown
export function backward(net, x, y, lr = 0.1) { const acts = forward(net, x), out = acts[acts.length - 1]; let delta = out.map((o, i) => o - y[i]); const norms = []; for (let l = net.layers.length - 1; l >= 0; l--) { const L = net.layers[l], a = acts[l]; norms[l] = Math.hypot(...delta); const prev = a.map((_, j) => sum(L.W.map((row, i) => row[j] * delta[i]))); for (let i = 0; i < L.W.length; i++) { for (let j = 0; j < a.length; j++) L.W[i][j] -= lr * delta[i] * a[j]; L.b[i] -= lr * delta[i]; } if (l > 0) { const d = ACT[net.layers[l - 1].act][1]; delta = prev.map((v, j) => v * d(a[j])); } } return { loss: -sum(y.map((t, i) => t * Math.log(Math.max(out[i], 1e-9)) + (1 - t) * Math.log(Math.max(1 - out[i], 1e-9)))), norms }; }
export function trainEpoch(net, X, Y, lr, rng) { let loss = 0; for (const i of rng.shuffle(X.map((_, j) => j))) loss += backward(net, X[i], Y[i], lr).loss; return loss / X.length; }
export const predict = (net, x) => { const a = forward(net, x); return a[a.length - 1]; };
// convolution of a small image with a kernel (valid padding), then pooling
export function conv2d(img, ker, stride = 1) { const h = img.length, w = img[0].length, k = ker.length, out = []; for (let y = 0; y + k <= h; y += stride) { const row = []; for (let x = 0; x + k <= w; x += stride) { let s = 0; for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) s += img[y + i][x + j] * ker[i][j]; row.push(s); } out.push(row); } return out; }
export function pool(img, size = 2, how = 'max') { const out = []; for (let y = 0; y + size <= img.length; y += size) { const row = []; for (let x = 0; x + size <= img[0].length; x += size) { const v = []; for (let i = 0; i < size; i++) for (let j = 0; j < size; j++) v.push(img[y + i][x + j]); row.push(how === 'max' ? Math.max(...v) : mean(v)); } out.push(row); } return out; }
// Hopfield network: store patterns of +1/-1, recall from a damaged copy
export function hopfield(patterns) { const n = patterns[0].length, W = Array.from({ length: n }, () => new Array(n).fill(0)); for (const p of patterns) for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (i !== j) W[i][j] += (p[i] * p[j]) / n; return { W, recall(s, sweeps = 5) { const x = s.slice(); for (let it = 0; it < sweeps; it++) for (let i = 0; i < n; i++) x[i] = W[i].reduce((a, w, j) => a + w * x[j], 0) >= 0 ? 1 : -1; return x; } }; }

// ---- choosing under uncertainty ----
export function banditRun(means, policy, rng, steps = 200, param = 0.1) { const k = means.length, n = new Array(k).fill(0), q = new Array(k).fill(0), a = new Array(k).fill(1), b = new Array(k).fill(1); let total = 0; const picks = [], regret = []; const best = Math.max(...means); let reg = 0; for (let t = 1; t <= steps; t++) { let arm; if (policy === 'greedy') arm = rng.chance(param) ? rng.int(0, k - 1) : q.indexOf(Math.max(...q)); else if (policy === 'ucb') { const u = q.map((v, i) => (n[i] ? v + param * Math.sqrt((2 * Math.log(t)) / n[i]) : Infinity)); arm = u.indexOf(Math.max(...u)); } else { const s = a.map((x, i) => betaSample(x, b[i], rng)); arm = s.indexOf(Math.max(...s)); } const r = rng.chance(means[arm]) ? 1 : 0; n[arm]++; q[arm] += (r - q[arm]) / n[arm]; a[arm] += r; b[arm] += 1 - r; total += r; reg += best - means[arm]; picks.push(arm); regret.push(reg); } return { n, q, total, picks, regret }; }
function gammaSample(k, rng) { if (k < 1) return gammaSample(k + 1, rng) * Math.pow(rng.u() || 1e-9, 1 / k); const d = k - 1 / 3, c = 1 / Math.sqrt(9 * d); for (;;) { const x = rng.n(), v = (1 + c * x) ** 3; if (v <= 0) continue; const u = rng.u() || 1e-9; if (Math.log(u) < 0.5 * x * x + d - d * v + d * Math.log(v)) return d * v; } }
export function betaSample(a, b, rng) { const x = gammaSample(a, rng), y = gammaSample(b, rng); return x / (x + y); }
// a grid world: cells are '.', '#' (wall), 'G' (goal, +1), 'X' (pit, -1), 'S' (start)
const MOVES = [[0, -1], [1, 0], [0, 1], [-1, 0]];
export function gridStep(grid, [x, y], a) { const nx = x + MOVES[a][0], ny = y + MOVES[a][1], c = grid[ny]?.[nx]; if (c === undefined || c === '#') return { pos: [x, y], r: -0.04, done: false }; return { pos: [nx, ny], r: c === 'G' ? 1 : c === 'X' ? -1 : -0.04, done: c === 'G' || c === 'X' }; }
export function qlearn(grid, rng, { episodes = 200, alpha = 0.5, gamma = 0.95, eps = 0.15, Q = null, sarsa = false } = {}) { const h = grid.length, w = grid[0].length; Q = Q || Array.from({ length: h }, () => Array.from({ length: w }, () => [0, 0, 0, 0])); let start = [0, 0]; for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (grid[y][x] === 'S') start = [x, y]; const pick = (p) => (rng.chance(eps) ? rng.int(0, 3) : Q[p[1]][p[0]].indexOf(Math.max(...Q[p[1]][p[0]]))); const returns = []; for (let e = 0; e < episodes; e++) { let p = start, a = pick(p), G = 0; for (let t = 0; t < 80; t++) { const s = gridStep(grid, p, a), a2 = pick(s.pos), q = Q[p[1]][p[0]]; const target = s.r + (s.done ? 0 : gamma * (sarsa ? Q[s.pos[1]][s.pos[0]][a2] : Math.max(...Q[s.pos[1]][s.pos[0]]))); q[a] += alpha * (target - q[a]); G += s.r; p = s.pos; a = a2; if (s.done) break; } returns.push(G); } return { Q, returns, start }; }
export function valueIteration(grid, gamma = 0.95, sweeps = 60) { const h = grid.length, w = grid[0].length; let V = Array.from({ length: h }, () => new Array(w).fill(0)); for (let s = 0; s < sweeps; s++) { const N = V.map((r) => r.slice()); for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { const c = grid[y][x]; if (c === '#' || c === 'G' || c === 'X') { N[y][x] = 0; continue; } N[y][x] = Math.max(...[0, 1, 2, 3].map((a) => { const st = gridStep(grid, [x, y], a); return st.r + (st.done ? 0 : gamma * V[st.pos[1]][st.pos[0]]); })); } V = N; } return V; }

// ---- games: noughts and crosses is small enough to solve ----
const LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
export function winner(b) { for (const [a, c, d] of LINES) if (b[a] && b[a] === b[c] && b[a] === b[d]) return b[a]; return b.every(Boolean) ? 'draw' : null; }
export function minimax(b, player, depth = 9, alpha = -Infinity, beta = Infinity, stats = { nodes: 0, pruned: 0 }, usePruning = true, me = player) { stats.nodes++; const w = winner(b); if (w) return { score: w === 'draw' ? 0 : w === me ? 10 - (9 - depth) * 0.01 : -10 + (9 - depth) * 0.01, stats }; if (depth === 0) return { score: heuristic(b, me), stats }; let best = { score: player === me ? -Infinity : Infinity, move: -1, stats }; for (let i = 0; i < 9; i++) { if (b[i]) continue; b[i] = player; const r = minimax(b, player === 'X' ? 'O' : 'X', depth - 1, alpha, beta, stats, usePruning, me); b[i] = null; if (player === me ? r.score > best.score : r.score < best.score) best = { score: r.score, move: i, stats }; if (usePruning) { if (player === me) alpha = Math.max(alpha, r.score); else beta = Math.min(beta, r.score); if (beta <= alpha) { stats.pruned++; break; } } } return best; }
function heuristic(b, me) { let s = 0; for (const L of LINES) { const m = L.filter((i) => b[i] === me).length, o = L.filter((i) => b[i] && b[i] !== me).length; if (m && !o) s += m; if (o && !m) s -= o; } return s; }
// Monte Carlo tree search (UCT) on noughts and crosses
export function mcts(board, player, rng, iters = 300, c = 1.4, prior = null) { const root = { b: board.slice(), p: player, n: 0, w: 0, kids: null, move: -1 }; const other = (p) => (p === 'X' ? 'O' : 'X'); const expand = (nd) => { nd.kids = []; for (let i = 0; i < 9; i++) if (!nd.b[i]) { const b = nd.b.slice(); b[i] = nd.p; nd.kids.push({ b, p: other(nd.p), n: 0, w: 0, kids: null, move: i }); } }; const rollout = (b, p) => { b = b.slice(); let w = winner(b); while (!w) { const free = b.map((v, i) => (v ? -1 : i)).filter((i) => i >= 0); let mv = free[rng.int(0, free.length - 1)]; if (prior) { const win = free.find((i) => { b[i] = p; const ww = winner(b) === p; b[i] = null; return ww; }); if (win !== undefined) mv = win; } b[mv] = p; p = other(p); w = winner(b); } return w; }; for (let it = 0; it < iters; it++) { const path = [root]; let nd = root; while (nd.kids && nd.kids.length && !winner(nd.b)) { nd = nd.kids.reduce((best, k) => { const u = k.n ? k.w / k.n + c * Math.sqrt(Math.log(nd.n + 1) / k.n) : Infinity; return u > best.u ? { u, k } : best; }, { u: -Infinity, k: null }).k; path.push(nd); } if (!winner(nd.b)) { expand(nd); if (nd.kids.length) { nd = nd.kids[rng.int(0, nd.kids.length - 1)]; path.push(nd); } } const w = winner(nd.b) || rollout(nd.b, nd.p); for (const x of path) { x.n++; const mover = other(x.p); x.w += w === 'draw' ? 0.5 : w === mover ? 1 : 0; } } return { root, best: root.kids.reduce((a, b) => (b.n > a.n ? b : a)).move, visits: root.kids.map((k) => [k.move, k.n, k.n ? k.w / k.n : 0]) }; }

// ---- cause and effect ----
// people: [{ y0, y1, x }], treated flags
export const trueATE = (people) => mean(people.map((p) => p.y1 - p.y0));
export function naiveDiff(people, treated) { const a = people.filter((_, i) => treated[i]).map((p) => p.y1), b = people.filter((_, i) => !treated[i]).map((p) => p.y0); return a.length && b.length ? mean(a) - mean(b) : NaN; }
export function ipw(y, treated, prop) { let a = 0, b = 0; for (let i = 0; i < y.length; i++) { if (treated[i]) a += y[i] / prop[i]; else b += y[i] / (1 - prop[i]); } return (a - b) / y.length; }
export function diffInDiff(t0, t1, c0, c1) { return mean(t1) - mean(t0) - (mean(c1) - mean(c0)); }
export function waldIV(z, d, y) { const z1 = z.map((v, i) => (v ? i : -1)).filter((i) => i >= 0), z0 = z.map((v, i) => (v ? -1 : i)).filter((i) => i >= 0); return (mean(z1.map((i) => y[i])) - mean(z0.map((i) => y[i]))) / (mean(z1.map((i) => d[i])) - mean(z0.map((i) => d[i]))); }

// ---- privacy ----
// randomised response: answer truthfully on heads, say yes on tails
export const rrAnswer = (truth, rng, pTruth = 0.5) => (rng.chance(pTruth) ? truth : true);
export const rrEstimate = (yesRate, pTruth = 0.5) => (yesRate - (1 - pTruth)) / pTruth;
export const laplace = (scale, rng) => { const u = rng.u() - 0.5; return -scale * Math.sign(u) * Math.log(1 - 2 * Math.abs(u)); };
